/**
 * The published changelog and installer links.
 *
 * `changelog.json` is generated by the release workflow — the same cumulative
 * feed the desktop app reads under Settings → Changelog — and committed here by
 * the "Publish the site changelog" step. Importing it at build time means the
 * version and the history are in the prerendered HTML rather than fetched after
 * hydration: a static host cannot read the release asset directly (GitHub sends
 * no CORS headers), and going through the API would spend a rate limit on a file
 * the release itself already deploys.
 */

import feed from './changelog.json';

export type ChangelogChange = { kind: string; text: string };

export type ChangelogRelease = {
	version: string;
	date: string;
	title: string;
	highlights: string[];
	changes: ChangelogChange[];
};

export type ChangelogFeed = {
	schema?: number;
	latest?: string;
	updatedAt?: string;
	releases: ChangelogRelease[];
};

/** The committed feed, newest release first. */
export const changelog: ChangelogFeed = feed as ChangelogFeed;

/** The version every download link points at. */
export const latest: string = changelog.latest || changelog.releases[0]?.version || '';

/** GitHub's asset URL for one published file. */
export function releaseAsset(version: string, file: string): string {
	return `https://github.com/StarkDroid/QuickNotch/releases/download/v${version}/${file}`;
}

/** The release page (notes, checksums, older builds). */
export function releasePage(version: string): string {
	return `https://github.com/StarkDroid/QuickNotch/releases/tag/v${version}`;
}

export type InstallerId = 'windows-msi' | 'mac-arm64' | 'mac-intel';

export type Installer = {
	id: InstallerId;
	platform: 'windows' | 'macos';
	label: string;
	detail: string;
	file: (version: string) => string;
};

/**
 * The file names the release workflow produces. They are derived from the
 * version in the changelog feed, so a new release never needs a site change.
 *
 * One installer per platform card except macOS, which needs a build per
 * architecture. The plain `.exe` the workflow also publishes is mentioned in
 * the Windows card's note and left on the release page rather than given a
 * second button: two links under one heading read as a choice the app does not
 * actually ask for.
 */
export const installers: Installer[] = [
	{
		id: 'windows-msi',
		platform: 'windows',
		label: 'Download for Windows',
		detail: '.msi · x64',
		file: (version) => `QuickNotch-${version}.msi`
	},
	{
		id: 'mac-arm64',
		platform: 'macos',
		label: 'Apple silicon',
		detail: '.dmg · M-series',
		file: (version) => `QuickNotch-${version}-arm64.dmg`
	},
	{
		id: 'mac-intel',
		platform: 'macos',
		label: 'Intel',
		detail: '.dmg · x64',
		file: (version) => `QuickNotch-${version}-x64.dmg`
	}
];

export function installersFor(platform: 'windows' | 'macos'): Installer[] {
	return installers.filter((installer) => installer.platform === platform);
}

/** Which card to mark as the visitor's machine, or null when it is neither. */
export function platformOf(userAgent: string): 'windows' | 'macos' | null {
	if (/Windows/i.test(userAgent)) return 'windows';
	if (/Macintosh|Mac OS X/i.test(userAgent)) return 'macos';
	return null;
}
